const results = await Promise.allSettled([
tools.exec_command({cmd:"rtk proxy rg -n 'editor|lag|live-review|Tiptap|autosave' /home/diogenes/.codex/memories/MEMORY.md",max_output_tokens:5000}),
tools.exec_command({cmd:"rtk proxy git status --short",max_output_tokens:3000}),
tools.exec_command({cmd:"rtk proxy rg --files -g 'AGENTS.md' -g 'package.json' -g '*editor*' -g '*Editor*' -g '*live-review*'",max_output_tokens:5000})
]); for(let i=0;i<results.length;i++) text({i,...results[i]});

const r=await Promise.allSettled([
tools.exec_command({cmd:"rtk proxy cat AGENTS.md package.json",max_output_tokens:6000}),
tools.exec_command({cmd:"rtk proxy rg -n 'onUpdate|onTransaction|onSelectionUpdate|addEventListener|setInterval|getJSON|getHTML|getText|requestAnimationFrame' src/components/editor/twyne-editor.tsx src/components/editor/extensions src/utils/live-review.ts src/components/editor/manuscript-panel.tsx",max_output_tokens:7000}),
tools.exec_command({cmd:"rtk proxy sed -n '238,258p' /home/diogenes/.codex/memories/MEMORY.md",max_output_tokens:2000})
]);r.forEach((x,i)=>text({i,...x}));

