            if (destroyed || view.isDestroyed) return;
            const layout = paginationPluginKey.getState(view.state)?.layout;
            if (!layout) return;

            const setup = resolvePageSetup(layout);
            const geometry = computePageGeometry(layout, rootFontSize());

