            },

            destroy() {
              destroyed = true;
              if (timer) clearTimeout(timer);
              if (rafId != null) cancelAnimationFrame(rafId);
              contentObserver?.disconnect();
              canvasObserver?.disconnect();
              fontSet?.removeEventListener?.("loadingdone", onFontsDone);
            },
          };
        },
      }),
    ];
  },
});

