/**
 * TipTap extension that paints a small hit-tested chip at the end of
 * every contiguous run of three "comment-like" marks: writer comments
 * (`.twyne-comment-mark`), persona notes (`.twyne-persona-note`), and
 * editor proposals (`.twyne-suggestion`).
 *
 * Why a widget and not a CSS pseudo-element:
 *   - Multi-span marks can interleave with bold/italic/links etc.,
 *     leaving no single DOM "last span" the CSS can target.
 *   - Pseudo-elements can't be hit-tested, so a chip clicked by
 *     the reader can't open the right popover.
 *   - Widgets are real DOM nodes owned by ProseMirror and survive
 *     mapping across transactions.
 *
 * The chip carries `data-anchor-kind` (note|comment|suggestion) and
 * `data-anchor-id`; the editor's click handler reads those and
 * forwards to the matching popover opener using the chip's own
 * getBoundingClientRect() (sidestepping multi-span rect issues).
 */
import { Extension } from "@tiptap/core";
import { Plugin, PluginKey } from "@tiptap/pm/state";
import type { Mark, Node as PmNode } from "@tiptap/pm/model";
import { Decoration, DecorationSet } from "@tiptap/pm/view";

export type AnchorKind = "note" | "comment" | "suggestion";

const anchorPluginKey = new PluginKey<DecorationSet>("twyneMarkAnchors");

/** Helper for both compilers: name → kind. */
function kindFor(name: string): AnchorKind | null {
  switch (name) {
    case "personaNote":
      return "note";
    case "commentMark":
      return "comment";
    case "suggestion":
      return "suggestion";
    default:
      return null;
  }
}

function idForMark(mark: Mark): string | null {
  const id = mark.attrs?.id;
  return typeof id === "string" && id.length > 0 ? id : null;
}

function buildDecorations(doc: PmNode): DecorationSet {
  const decos: Decoration[] = [];

  // Walk every text node in document order. For each text node we
  // inspect its marks; for the first anchored mark we find, we emit
  // a widget at the *end* of the contiguous (kind, id) run that
  // begins at this text node's start position.
  doc.descendants((node: PmNode, pos: number) => {
    if (!node.isText || !node.marks.length) return true;

    for (const mark of node.marks) {
      const kind = kindFor(mark.type.name);
      if (!kind) continue;
      const id = idForMark(mark);
      if (!id) continue;

      // Detect whether this text node continues a previous run of
      // the same (kind, id) marks. We only need the immediately
      // preceding position; if it carries the same mark, this node
      // is a continuation and the chip is emitted from the *start*
      // of the run (handled by the first node in the run).
      const prevPos = pos - 1;
      const continues =
        prevPos >= 0 &&
        doc
          .resolve(prevPos)
          .marks()
          .some((m) => kindFor(m.type.name) === kind && idForMark(m) === id);
      if (continues) continue;

      // Otherwise this is the start of a new run: scan forward to
      // find the run end. The simplest correct definition: walk
      // forward from this node's end position; the latest position
      // at which the (kind, id) marks still appear is the run end.
      const runStart = pos;
      const runEnd = findRunEnd(doc, kind, id, runStart);
      // Place the chip *at* the run end (after the last character
      // of the marked span) with side: 1 so it sits outside the
      // marked text rather than inside the next character.
      decos.push(
        Decoration.widget(runEnd, () => createChip(kind, id), {
          // Stable identity, so ProseMirror reuses the chip's DOM instead of
          // recreating it on every keystroke. Without a key the whole set is
          // rebuilt on each doc change, which both costs layout and makes the
          // pagination engine's ResizeObserver fire far more than it should.
          key: `twyne-anchor:${kind}:${id}`,
          side: 1,
          ignoreSelection: true,
        }),
      );
    }
    return true;
  });

  return DecorationSet.create(doc, decos);
}

function findRunEnd(
  doc: PmNode,
  kind: AnchorKind,
  id: string,
  fromPos: number,
): number {
  let last = fromPos;
  doc.descendants((node, pos) => {
    if (pos + node.nodeSize <= fromPos) return true;
    if (!node.isText) return true;
    const has = node.marks.some(
      (m) => kindFor(m.type.name) === kind && idForMark(m) === id,
    );
    if (has) last = pos + node.nodeSize;
    return true;
  });
  return last;
}

function createChip(kind: AnchorKind, id: string): HTMLButtonElement {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "twyne-mark-anchor";
  btn.setAttribute("data-anchor-kind", kind);
  btn.setAttribute("data-anchor-id", id);
  btn.setAttribute("aria-label", `Open ${kind}`);
  btn.contentEditable = "false";
  return btn;
}

export const MarkAnchorWidgets = Extension.create({
  name: "markAnchorWidgets",

  addProseMirrorPlugins() {
    return [
      new Plugin<DecorationSet>({
        key: anchorPluginKey,
        state: {
          init: (_, state) => buildDecorations(state.doc),
          apply(tr, old, _oldState, newState) {
            if (tr.docChanged) {
              // On doc changes, rebuild — the set of runs and the
              // text nodes they live on may all have shifted, so a
              // plain mapping isn't faithful.
              return buildDecorations(newState.doc);
            }
            return old.map(tr.mapping, tr.doc);
          },
        },
        props: {
          decorations(state) {
            return this.getState(state);
          },
        },
      }),
    ];
  },
});
import { Extension } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import { Plugin, PluginKey } from "@tiptap/pm/state";
import { Decoration, DecorationSet } from "@tiptap/pm/view";
import {
  illuminatedInitialArtwork,
  openingInitial,
} from "../../../utils/illuminated-initials";
import {
  DEFAULT_OPENING_INITIAL,
  resolveOpeningInitial,
  type OpeningInitialSettings,
} from "../../../types";

interface InitialLocation {
  paragraphFrom: number;
  paragraphTo: number;
  prefixFrom: number | null;
  from: number;
  to: number;
  artwork: string | null;
}

interface IlluminatedInitialState {
  initial: InitialLocation | null;
  settings: OpeningInitialSettings;
  loaded: ReadonlySet<string>;
  decorations: DecorationSet;
}

type InitialMeta =
  | { type: "settings"; settings: OpeningInitialSettings }
  | { type: "loaded"; artwork: string };

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    illuminatedInitial: {
      setOpeningInitial: (settings: OpeningInitialSettings) => ReturnType;
    };
  }
}

export const illuminatedInitialPluginKey =
  new PluginKey<IlluminatedInitialState>("twyneIlluminatedInitial");

function findInitial(
  doc: ProseMirrorNode,
  settings: OpeningInitialSettings,
): InitialLocation | null {
  if (settings.mode === "off") return null;
  let initial: InitialLocation | null = null;
  let foundParagraph = false;
  doc.forEach((node, offset) => {
    if (foundParagraph || node.type.name !== "paragraph") return;
    foundParagraph = true;
    // Leaf atoms occupy one position, so text offsets still match the document.
    // An opening image/note/equation must not illuminate unrelated later text.
    const text = node.textBetween(0, node.content.size, "", "\ufffc");
    const opening = openingInitial(text);
    // Keep the existing typographic cap for unsupported graphemes. In
    // particular, a combining accent can straddle differently marked nodes;
    // floating multiple decoration fragments would separate that grapheme.
    if (!opening?.artwork) return;
    const prefixStart = text.slice(0, opening.from).search(/\S/u);
    initial = {
      paragraphFrom: offset,
      paragraphTo: offset + node.nodeSize,
      prefixFrom: prefixStart < 0 ? null : offset + 1 + prefixStart,
      from: offset + 1 + opening.from,
      to: offset + 1 + opening.to,
      artwork:
        settings.mode === "illuminated"
          ? illuminatedInitialArtwork(opening.glyph, settings.collection)
          : null,
    };
  });
  return initial;
}

function decorate(
  doc: ProseMirrorNode,
  loaded: ReadonlySet<string>,
  settings: OpeningInitialSettings,
): IlluminatedInitialState {
  const initial = findInitial(doc, settings);
  if (!initial)
    return { initial, settings, loaded, decorations: DecorationSet.empty };
  const ready = initial.artwork && loaded.has(initial.artwork);
  return {
    initial,
    settings,
    loaded,
    decorations: DecorationSet.create(doc, [
      Decoration.node(initial.paragraphFrom, initial.paragraphTo, {
        class: "twyne-illuminated-paragraph",
      }),
      // Floats otherwise pass preceding inline punctuation and make “At read
      // as A “t. Keep the real quote/bracket to the left of the initial.
      ...(initial.prefixFrom === null
        ? []
        : [
            Decoration.inline(initial.prefixFrom, initial.from, {
              nodeName: "span",
              class: "twyne-illuminated-prefix",
            }),
          ]),
      Decoration.inline(initial.from, initial.to, {
        nodeName: "span",
        class: `twyne-illuminated-initial${ready ? " is-illuminated" : ""}`,
        ...(ready
          ? { style: `--twyne-initial-artwork: url("${initial.artwork}")` }
          : {}),
      }),
    ]),
  };
}

/** A view decoration, never a mark/node: copy, autosave and source retain text. */
export const IlluminatedInitial = Extension.create<{
  settings: OpeningInitialSettings;
}>({
  name: "illuminatedInitial",

  addOptions() {
    return { settings: { ...DEFAULT_OPENING_INITIAL } };
  },

  addCommands() {
    return {
      setOpeningInitial:
        (settings) =>
        ({ tr, dispatch }) => {
          if (dispatch)
            tr.setMeta(illuminatedInitialPluginKey, {
              type: "settings",
              settings: resolveOpeningInitial({ openingInitial: settings }),
            } satisfies InitialMeta).setMeta("addToHistory", false);
          return true;
        },
    };
  },

  addProseMirrorPlugins() {
    const settings = resolveOpeningInitial({
      openingInitial: this.options.settings,
    });
    return [
      new Plugin<IlluminatedInitialState>({
        key: illuminatedInitialPluginKey,
        state: {
          init: (_, state) => decorate(state.doc, new Set(), settings),
          apply(tr, previous) {
            const meta = tr.getMeta(illuminatedInitialPluginKey) as
              | InitialMeta
              | undefined;
            if (meta?.type === "settings")
              return decorate(tr.doc, previous.loaded, meta.settings);
            if (meta?.type === "loaded")
              return decorate(
                tr.doc,
                new Set([...previous.loaded, meta.artwork]),
                previous.settings,
              );
            return tr.docChanged
              ? decorate(tr.doc, previous.loaded, previous.settings)
              : previous;
          },
        },
        props: {
          attributes(state) {
            const settings =
              illuminatedInitialPluginKey.getState(state)?.settings;
            return {
              "data-opening-initial-mode": settings?.mode ?? "illuminated",
              "data-opening-initial-size": settings?.size ?? "medium",
              "data-opening-initial-collection":
                settings?.collection ?? "botanical",
            };
          },
          decorations: (state) =>
            illuminatedInitialPluginKey.getState(state)?.decorations,
        },
        view(view) {
          const attempted = new Set<string>();
          const pending = new Set<HTMLImageElement>();
          let destroyed = false;
          const preload = () => {
            const artwork = illuminatedInitialPluginKey.getState(view.state)
              ?.initial?.artwork;
            if (!artwork || attempted.has(artwork)) return;
            attempted.add(artwork);
            const image = view.dom.ownerDocument.createElement("img");
            image.decoding = "async";
            pending.add(image);
            let settled = false;
            const done = (loaded: boolean) => {
              if (settled) return;
              settled = true;
              image.onload = image.onerror = null;
              pending.delete(image);
              if (!loaded || destroyed || view.isDestroyed) return;
              view.dispatch(
                view.state.tr
                  .setMeta(illuminatedInitialPluginKey, {
                    type: "loaded",
                    artwork,
                  } satisfies InitialMeta)
                  .setMeta("addToHistory", false),
              );
            };
            image.onload = () => done(image.naturalWidth > 0);
            image.onerror = () => done(false);
            image.src = artwork;
            if (image.complete && image.naturalWidth > 0)
              queueMicrotask(() => done(true));
          };
          preload();
          return {
            update: preload,
            destroy() {
              destroyed = true;
              for (const image of pending) image.onload = image.onerror = null;
              pending.clear();
            },
          };
        },
      }),
    ];
  },
});

