            expect(reopened.html).toBe(remote.html);
            expect(reopened.states.at(-1)).toMatchObject({
              source,
              dirty: true,
              conflict: true,
              error:
                "Resolve the newer manuscript conflict before applying this draft.",
            });
          } finally {
