    if (i >= body.length) {
      if (result.length) result[result.length - 1].source += body.slice(begin);
      break;
    }
    if (body.startsWith("#twyne-node(", i)) {
      try {
        const p = parseWrapper(body, i, 0);
        result.push({ source: body.slice(begin, p.end), html: p.html });
