    let end: number;
    try {
      end = paragraphEnd(body, i);
    } catch {
      end = body.length;
    }
    const s = body.slice(i, end);
    let html: string;
    try {
      const heading = /^(={1,6})\s+([\s\S]*)$/.exec(s);
