    await cdp.send("Emulation.setCPUThrottlingRate", {rate: 4});
    await page.evaluate(() => {
      const target = window as unknown as BenchWindow;
      const editor = (document.querySelector(".ProseMirror") as HTMLElement & {editor: Editor}).editor;
      const samples: TypingSamples = {dispatch: [], frame: [], queue: [], longTasks: []};
      target.typingBench = samples;
      const original = editor.view.dispatch;
      editor.view.dispatch = (tr) => {
        const start = performance.now();
        original.call(editor.view, tr);
        if (tr.docChanged) samples.dispatch.push(performance.now() - start);
      };
      const input = (event: Event) => {
        samples.queue.push(Math.max(0, performance.now() - event.timeStamp));
        requestAnimationFrame(() => samples.frame.push(performance.now() - event.timeStamp));
      };
      editor.view.dom.addEventListener("beforeinput", input, true);
      const observer = new PerformanceObserver((list) => samples.longTasks.push(...list.getEntries().map((e) => e.duration)));
      observer.observe({type: "longtask"});
      target.stopTypingBench = () => {
        observer.disconnect();
        editor.view.dispatch = original;
        editor.view.dom.removeEventListener("beforeinput", input, true);
      };
    });
    for (let repeat = 0; repeat < 3; repeat++) {
      for (let phase = 0; phase < 3; phase++) {
        await page.keyboard.type(burst, {delay: 15});
        await page.waitForTimeout(phase % 2 ? 1100 : 550);
      }
    }
    await page.waitForTimeout(1500);
    const samples = await page.evaluate(() => {
      const target = window as unknown as BenchWindow;
      target.stopTypingBench();
      return target.typingBench;
    });
    await cdp.send("Emulation.setCPUThrottlingRate", {rate: 1});
    const report = typingReport(`${paragraphs} annotated paragraphs · 4x CPU`, samples, {
      paragraphs, cpuThrottle: 4, repeats: 3, keystrokes: burst.length * 9,
      browser: browser.version(), build: "Vite development", platform: process.platform,
      architecture: process.arch, commit: process.env.GITHUB_SHA ?? "local", timestamp: new Date().toISOString(),
      budgets: {dispatchP95: 100, dispatchP99: 200, frameP95: 200, frameP99: 400},
    });
    for (const [name, body, contentType] of [
      ["typing-latency.json", JSON.stringify(report.json, null, 2), "application/json"],
      ["typing-latency.html", report.html, "text/html"],
      ["typing-percentiles.svg", report.svg, "image/svg+xml"],
      ["typing-histogram.svg", report.histogramSvg, "image/svg+xml"],
    ]) {
      const path = info.outputPath(name);
      await writeFile(path, body);
      await info.attach(name, {path, contentType});
    }
    const chart = await page.context().newPage();
    await chart.setContent(report.html);
    await chart.screenshot({path: info.outputPath("typing-charts.png"), fullPage: true});
    await info.attach("typing-charts.png", {path: info.outputPath("typing-charts.png"), contentType: "image/png"});
    await chart.close();
    // Verify measured edits reached source and survived a real reload as well.
    expect(samples.frame).toHaveLength(burst.length * 9);
    expect(samples.dispatch.length).toBeGreaterThanOrEqual(burst.length * 9);
    expect(report.json.metrics["Editor transaction"].p95).toBeLessThan(100);
    expect(report.json.metrics["Editor transaction"].p99).toBeLessThan(200);
    expect(report.json.metrics["Input to next frame"].p95).toBeLessThan(200);
    expect(report.json.metrics["Input to next frame"].p99).toBeLessThan(400);
    await page.getByRole("button", {name: "Source", exact: true}).click();
    await expect(page.locator(".typst-source-editor .cm-content")).toContainText(burst.trim());
    await page.reload();
    await expect(page.locator(".ProseMirror")).toContainText(burst.repeat(9).trim());
  });
}
