import { distribution, type TypingSamples } from "../e2e/helpers/typing-report";

const [beforePath, afterPath, output = "test-results/typing-comparison"] = process.argv.slice(2);
if (!beforePath || !afterPath) throw new Error("Usage: bun scripts/compare-typing.ts BEFORE.json AFTER.json [output-directory]");
const before = JSON.parse(await readFile(beforePath, "utf8"));
