    const w = n / ceiling * 580;
    return `<rect x="260" y="${y + j * 24}" width="${w}" height="18" fill="${j ? "#b4412d" : "#9d9285"}"/><text x="${270 + w}" y="${y + j * 24 + 14}" font-size="13">${n.toFixed(1)} ms</text>`;
  }).join("")}`;
}).join("")}</g></svg>`;
await mkdir(output, {recursive: true});
await writeFile(join(output, "comparison.svg"), svg);
await writeFile(join(output, "comparison.html"), `<!doctype html><html lang="en"><meta charset="utf-8"><title>Typing comparison</title><style>body{margin:24px;background:#f6f2e9;color:#29251f;font:16px system-ui}svg{width:100%;max-width:1000px;height:auto}p{max-width:1000px;line-height:1.5}</style>${svg}<p>Input-to-frame ends at the next animation-frame callback, before paint. Long tasks cover background work as well as typing. Samples use sequential native Playwright keyboard input. Both runs use matching machine, browser and development-build metadata. Absolute values are not physical-device or production-build measurements.</p></html>`);
await writeFile(join(output, "comparison.json"), JSON.stringify({before: before.metadata, after: after.metadata, bars}, null, 2));
console.log(join(output, "comparison.html"));
EOF
